/**
 * Maps each page template to a view and type-checks the mapping. `defineTemplates<MoteurSchema>({ home: Home, … })`
 * fails `astro check` when a template has no view or when a view reads fields that its template does not have.
 */
import type { SchemaShape } from '@moteurio/client';

/** The properties a view can read from any page: its template and its URL path. */
export type DeliveredPageLike = { templateId: string; path: string };

/** The project's pages in a single language, as the loader provides them, taken from the types generated by `moteur types`. */
type PagesOf<S extends SchemaShape> = S['one'] extends {
    pages: infer P extends DeliveredPageLike;
}
    ? P & { locale: S['locale'] }
    : DeliveredPageLike & { locale: string };

/** A page as the `moteurPages` loader provides it, typed by its template and with its `locale`. */
export type SitePage<S extends SchemaShape> = PagesOf<S>;

/** The ids of the project's templates. */
export type TemplateId<S extends SchemaShape> = PagesOf<S>['templateId'];

/** A page of one template as the loader provides it, for example `PageOf<MoteurSchema, 'home'>`. */
export type PageOf<S extends SchemaShape, T extends TemplateId<S>> = Extract<
    PagesOf<S>,
    { templateId: T }
>;

/**
 * The props of a template's view, used as `type Props = ViewProps<MoteurSchema, 'home'>`. They
 * are the page, with its fields typed by the template, plus `path`, `paths` and `locale`.
 */
export type ViewProps<S extends SchemaShape, T extends TemplateId<S>> = {
    page: PageOf<S, T>;
};

/** An Astro component, or any function component, that renders a template. */
export type TemplateView<P extends DeliveredPageLike> = (props: { page: P }) => unknown;

/** A view for every template of the project, keyed by template id. */
export type TemplateViews<S extends SchemaShape> = {
    [P in PagesOf<S> as P['templateId']]: TemplateView<P>;
};

export interface DefinedTemplates {
    /** Returns the view for this page, or undefined for a template that has no view in the site. */
    for(page: DeliveredPageLike): TemplateView<DeliveredPageLike> | undefined;
}

const warned = new Set<string>();

export function defineTemplates<S extends SchemaShape>(views: TemplateViews<S>): DefinedTemplates {
    const map = views as unknown as Record<string, TemplateView<DeliveredPageLike>>;
    return {
        for(page) {
            const found = map[page.templateId];
            if (!found && !warned.has(page.templateId)) {
                // Skip pages whose template has no view in the site yet instead of failing the build.
                warned.add(page.templateId);
                console.warn(
                    `[moteur] No view for template "${page.templateId}": its pages (${page.path}, …) are not built.`
                );
            }
            return found;
        }
    };
}
